import{CardBattle}from'./card-battle.js';import{freshSave,CHIPS}from'./core.js';import{validateDeck}from'./deck.js';
const standardInventory=()=>Object.fromEntries(Object.entries(CHIPS).map(([id,c])=>[id,c.type==='equipment'?0:id==='gold'?0:3]));
export const DUEL_PRESETS={balanced:['cannon','cannon','thunder','thunder','longsword','longsword','recover','recover','barrier','barrier','gust','focus'],frost:['icewave','icewave','thunder','thunder','slow','slow','chainlight','barrier','barrier','focus','recover','draw'],garden:['poison','poison','bloom','bloom','thorns','thorns','stonewall','cannon','cannon','vampire','focus','draw'],blade:['longsword','longsword','cleave','cleave','dash','dash','charge','barrier','recover','focus','echo','gust']};
class DuelFighter extends CardBattle{
 constructor(options){super({...options,mission:{enemies:['hex']}});this.peer=null;this.p.hp=400;this.p.max=400;this.frozenUntil=0;this.wetUntil=0;this.duel=true;this.enemies[0].hp=400;this.enemies[0].max=400;this.enemies[0].boss=false;this.enemies[0].attackAt=Infinity;this.enemies[0].moveAt=Infinity;this.enemies[0].name='Rival';}
 damageEnemy(e,amount,element='neutral',leech=false){if(!this.peer||this.peer.p.hp<=0)return 0;const before=this.peer.p.hp;super.damageEnemy(e,amount,element,false);const raw=Math.min(before,Math.max(0,before-e.hp));this.peer.damagePlayer(raw);e.hp=this.peer.p.hp;if(this.peer.p.hp>0&&this.peer.status==='lost')this.peer.status='running';const actual=before-this.peer.p.hp;if(leech)this.p.hp=Math.min(this.p.max,this.p.hp+Math.floor(actual/2));return actual;}
 damagePlayer(amount){super.damagePlayer(amount);if(this.p.inv>.12)this.p.inv=.12;}
 move(dx,dy){if(this.frozenUntil>this.time)return false;return super.move(dx,dy);}
 shoot(){if(this.time-this.p.shotAt<.4)return;super.shoot();}
 useCard(slot){this.syncEnemy();const result=super.useCard(slot);if(result&&this.peer){const e=this.enemies[0];if(e.x!==5-this.peer.p.x)this.peer.p.x=Math.max(0,Math.min(2,5-e.x));if(e.frozen>this.time)this.peer.frozenUntil=Math.max(this.peer.frozenUntil,this.peer.time+e.frozen-this.time);if(e.wet>this.time)this.peer.wetUntil=Math.max(this.peer.wetUntil,this.peer.time+e.wet-this.time);if(e.poisonUntil>this.time){this.peer.poisonUntil=this.peer.time+e.poisonUntil-this.time;this.peer.poisonNext=this.peer.time+1;e.poisonUntil=0;}e.hp=this.peer.p.hp;}return result;}
 syncEnemy(){if(!this.peer)return;const e=this.enemies[0];e.hp=this.peer.p.hp;e.max=this.peer.p.max;e.x=5-this.peer.p.x;e.y=this.peer.p.y;e.wet=this.peer.wetUntil>this.peer.time?this.time+this.peer.wetUntil-this.peer.time:0;e.frozen=this.peer.frozenUntil>this.peer.time?this.time+this.peer.frozenUntil-this.peer.time:0;e.attackAt=Infinity;e.moveAt=Infinity;}
}
export class Duel{
 constructor({decks=[DUEL_PRESETS.balanced,DUEL_PRESETS.frost],operators=['pulse','nova'],seed=1,bot=false}={}){const inventory=standardInventory();if(decks.some(d=>!validateDeck(d,inventory,CHIPS)))throw Error('Duel decks must contain 12 standard cards, at most 3 copies each');this.fighters=decks.map((deck,i)=>new DuelFighter({deck,operator:operators[i],seed:seed+i*91}));this.fighters[0].peer=this.fighters[1];this.fighters[1].peer=this.fighters[0];this.status='ready';this.time=0;this.winner=null;this.bot=bot;this.botAt=0;this.events=[];}
 start(){if(this.status!=='ready')return;this.status='running';for(const f of this.fighters)f.start();}
 pause(){if(this.status==='running'){this.status='paused';for(const f of this.fighters)if(f.status==='running')f.pause();}else if(this.status==='paused'){this.status='running';for(const f of this.fighters)if(f.status==='paused')f.pause();}}
 useCard(player,slot){if(this.status!=='running')return false;const f=this.fighters[player];f.syncEnemy();const ok=f.useCard(slot);this.check();return ok;}
 resolve(player){if(this.status!=='running')return false;this.fighters[player].syncEnemy();const ok=this.fighters[player].overdrive();this.check();return ok;}
 check(){const [a,b]=this.fighters;if(a.p.hp<=0||b.p.hp<=0){this.status='finished';this.winner=a.p.hp===b.p.hp?null:a.p.hp>0?0:1;for(const f of this.fighters)f.status=f.p.hp>0?'won':'lost';this.events.push({type:'duelEnd',winner:this.winner,time:this.time});}}
 botInput(){const bot=this.fighters[1],foe=this.fighters[0];let dy=Math.sign(foe.p.y-bot.p.y);if(foe.shots.some(s=>s.y===bot.p.y&&s.x>2.7))dy=bot.p.y===2?-1:1;if(this.time>=this.botAt){this.botAt=this.time+.7;const slots=bot.cards.hand.map((id,i)=>({id,i})).filter(x=>x.id&&bot.cards.canPlay(x.i));const choice=slots.find(x=>CHIPS[x.id].type==='attack')??slots[0];if(choice)this.useCard(1,choice.i);if(bot.p.charge>=100)this.resolve(1);}return{dy,dx:bot.p.x<1?1:0,fire:true};}
 update(dt,inputs=[{},{}]){if(this.status!=='running')return;dt=Math.max(0,Math.min(.05,dt));this.time+=dt;if(this.bot)inputs=[inputs[0],this.botInput()];for(let i=0;i<2;i++){const f=this.fighters[i];f.syncEnemy();f.update(dt,inputs[i]??{});this.check();if(this.status==='finished')break;}}
 drain(){const events=this.events.splice(0);this.fighters.forEach((f,player)=>events.push(...f.drain().map(e=>({...e,player}))));return events;}
}
